#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Compile projects generated by the public CLI against this kit checkout."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import tempfile

from starter_sources import KIT_PACKAGES, ROOT

UI_TEST = r'''// SPDX-License-Identifier: GPL-3.0-or-later
use slint::{ComponentHandle, platform::{Key, PointerEventButton, WindowEvent}};
use i_slint_backend_testing::{ElementHandle, TestingBackend, TestingBackendOptions};
#[test]
fn generated_window_connects_pointer_keyboard_and_theme() {
    slint::platform::set_platform(Box::new(TestingBackend::new(TestingBackendOptions {
        mock_time: true, renderer_name: Some("software".into()), ..Default::default()
    }))).unwrap();
    let app = kit_scaffold_desktop::create().unwrap();
    app.show().unwrap();
    app.window().take_snapshot().unwrap();
    let button = ElementHandle::find_by_accessible_label(&app, "Run action").next().unwrap();
    button.mock_single_click(PointerEventButton::Left);
    assert_eq!(app.get_status(), "Done");
    app.set_status("Waiting for keyboard".into());
    for event in [WindowEvent::KeyPressed { text: Key::Space.into() }, WindowEvent::KeyReleased { text: Key::Space.into() }] {
        app.window().dispatch_event(event);
    }
    assert_eq!(app.get_status(), "Done");
    for (name, base) in [("light", app.get_theme()), ("dark", app.global::<slint_kit::ui::KitThemes>().get_dark())] {
        for scale in [1, 2] {
            let mut theme = base.clone(); theme.text_scale = if scale == 1 { 1. } else { 2. };
            app.set_theme(theme); slint::platform::update_timers_and_animations();
            let image = app.window().take_snapshot().unwrap();
            assert!(image.width() >= 420, "the window must honor its preferred width");
            assert!(f64::from(button.absolute_position().x + button.size().width) <= f64::from(image.width()), "the action must fit at enlarged text");
            let directory = std::env::var_os("KIT_SCAFFOLD_CAPTURE_DIR").unwrap();
            use std::io::Write;
            let mut file = std::fs::File::create(std::path::PathBuf::from(directory).join(format!("scaffold-{name}-{scale}.ppm"))).unwrap();
            write!(file, "P6\n{} {}\n255\n", image.width(), image.height()).unwrap();
            for pixel in image.as_slice() { file.write_all(&[pixel.r, pixel.g, pixel.b]).unwrap(); }
        }
    }
}
'''


def run(arguments, **options):
    subprocess.run(arguments, cwd=ROOT, check=True, **options)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--registry', action='store_true', help='resolve published kit packages instead of applying checkout patches')
    parser.add_argument('--web', action='store_true', help='also check the WASM library target')
    parser.add_argument('--capture-dir', type=Path, help='exercise the generated UI with the testing backend and save Software snapshots')
    parser.add_argument('--proof', type=Path)
    args = parser.parse_args()
    patches = []
    for package, directory in KIT_PACKAGES.items():
        patches += ['--config', f'patch.crates-io.{package}.path={json.dumps(str(ROOT / directory))}']
    if args.registry:
        patches = []
    proof = {'projects': {}, 'checks': [], 'kit_source': 'registry' if args.registry else 'checkout'}
    def save_proof():
        if args.proof:
            args.proof.parent.mkdir(parents=True, exist_ok=True)
            args.proof.write_text(json.dumps(proof, indent=2) + '\n')
    with tempfile.TemporaryDirectory(prefix='slint-kit-generated-') as temporary:
        for label, target in [('desktop', []), ('web', ['--web'])]:
            project = Path(temporary) / label
            run(['cargo', 'run', '--locked', '-p', 'slint-kit-cli', '--', 'new', str(project), '--name', f'kit-scaffold-{label}', *target])
            proof['projects'][label] = {str(path.relative_to(project)): hashlib.sha256(path.read_bytes()).hexdigest()
                                        for path in sorted(project.rglob('*')) if path.is_file()}
            manifest = ['--manifest-path', str(project / 'Cargo.toml'), *patches]
            save_proof()
            run(['cargo', 'fmt', '--manifest-path', str(project / 'Cargo.toml'), '--', '--check'])
            if label != 'desktop' or not args.capture_dir:
                run(['cargo', 'check', *manifest])
                proof['checks'].append(f'{label}: native cargo check passed')
                if args.registry:
                    metadata = json.loads(subprocess.check_output(['cargo', 'metadata', *manifest, '--format-version', '1'], cwd=ROOT, text=True))
                    kits = {package['name']: {'version': package['version'], 'source': package['source']}
                            for package in metadata['packages'] if package['name'] in KIT_PACKAGES}
                    if not kits or any(not (package['source'] or '').startswith('registry+') for package in kits.values()):
                        raise ValueError('Registry smoke project resolved a kit checkout')
                    proof['projects'][label + '-resolved-kits'] = kits
                save_proof()
            if label == 'web' and args.web:
                target_directory = os.environ.get('SLINT_WEB_TARGET_DIR', str(ROOT / 'target/scaffold-web'))
                run(['cargo', 'check', *manifest, '--lib', '--target', 'wasm32-unknown-unknown', '--target-dir', target_directory])
                proof['checks'].append('web: wasm32 library cargo check passed')
                save_proof()
            if label == 'desktop' and args.capture_dir:
                args.capture_dir.mkdir(parents=True, exist_ok=True)
                # Test-only backend admission; keep the generated application
                # Rust/UI bytes intact and record the public manifest above.
                with (project / 'Cargo.toml').open('a') as output:
                    output.write('\n[dev-dependencies]\ni-slint-backend-testing = { version = "=1.18.1", features = ["renderer-software"] }\n')
                (project / 'tests').mkdir()
                (project / 'tests/ui.rs').write_text(UI_TEST)
                run(['cargo', 'test', *manifest, '--test', 'ui'], env={**os.environ, 'SLINT_EMIT_DEBUG_INFO': '1', 'KIT_SCAFFOLD_CAPTURE_DIR': str(args.capture_dir.resolve())})
                proof['checks'].append('desktop: native pointer/keyboard callback and four theme/scale Software snapshots passed')
                save_proof()
    if args.proof:
        args.proof.parent.mkdir(parents=True, exist_ok=True)
        args.proof.write_text(json.dumps(proof, indent=2) + '\n')
    print('Generated desktop and web project checks passed', flush=True)


if __name__ == '__main__':
    main()
